$ErrorActionPreference='Continue'
$Root=Join-Path $env:LOCALAPPDATA 'JARBAS_Enterprise';$Manifest=Join-Path $Root 'PAYLOAD_MANIFEST_SHA256.txt';if(-not(Test-Path $Manifest)){Write-Host 'Manifesto instalado nao encontrado.' -ForegroundColor Red;exit 2};$bad=0;foreach($line in Get-Content $Manifest){if($line -notmatch '^([a-fA-F0-9]{64})\s+(.+)$'){continue};$expected=$Matches[1].ToLower();$rel=$Matches[2];$p=Join-Path $Root $rel;if(-not(Test-Path $p)){Write-Host "AUSENTE: $rel" -ForegroundColor Red;$bad++;continue};$actual=(Get-FileHash -Algorithm SHA256 $p).Hash.ToLower();if($actual -ne $expected){Write-Host "ALTERADO: $rel" -ForegroundColor Yellow;$bad++}};if($bad -eq 0){Write-Host 'Integridade do nucleo: OK' -ForegroundColor Green;exit 0}else{Write-Host "Arquivos com divergencia: $bad" -ForegroundColor Red;exit 3}
